{
 "research_question": "Does changing the offensive five (lineup) itself influence the shot mix of a team?",
 "retrieval_summary": {
  "prior_findings": [
   {
    "id": "2026-10-29-lineup-shot-mix-pilot",
    "status": "supported",
    "summary": "The pilot study found statistically significant shifts in shot mix (specifically, changes in the proportion of shots taken from different zones and shot types) when the offensive lineup changed, suggesting that personnel effects on shot selection are detectable."
   }
  ],
  "failed_experiments": [],
  "limitations": [
   {
    "id": "2026-10-29-lineup-shot-mix-pilot",
    "text": "The pilot study used a limited sample (one team, one season) and did not fully control for opponent defensive scheme or game state, which could confound the observed shot mix changes."
   }
  ],
  "unresolved": [
   {
    "id": "2026-10-29-lineup-shot-mix-pilot",
    "text": "The pilot study left open the question of how to robustly control for confounding factors like opponent defensive scheme and game state across a broader dataset to isolate the pure personnel effect."
   }
  ]
 },
 "evidence_use": "The retrieved pilot study (2026-10-29-lineup-shot-mix-pilot) directly addressed a similar question and found support for the hypothesis that offensive lineup changes affect shot mix. This provides initial evidence that the phenomenon is detectable. However, the study's limitations regarding sample size and control for confounding factors (opponent defense, game state) highlight critical areas for improvement in a more comprehensive study. The unresolved question about robust controls directly informs the design of the proposed research, emphasizing the need for a sophisticated control strategy.",
 "testability": {
  "p_testable": 0.8,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "2026-10-29-lineup-shot-mix-pilot"
  ],
  "summary": "A pilot study (2026-10-29-lineup-shot-mix-pilot) found preliminary evidence that changes in offensive lineups correlate with shifts in shot mix. However, this work was limited in scope (single team, single season) and did not fully account for confounding factors like opponent defensive schemes or game state, leaving the question of robust control open."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Changes in shot mix could be heavily confounded by the opponent's defensive scheme, game state (score, time), or even coaching instructions rather than solely by the offensive personnel change itself. Robust controls are essential."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Many specific five-player lineups may have limited minutes played together, leading to sparse data for certain combinations and making it difficult to detect statistically significant effects for individual lineups."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While the overall dataset is large, the number of distinct lineup changes and sufficient possessions within each lineup context might be insufficient to detect subtle but real changes in shot mix with adequate power, especially after controlling for multiple factors."
  }
 ],
 "predicted_outcome": {
  "supported": 0.6,
  "rejected": 0.1,
  "untestable": 0.15,
  "artifact": 0.1,
  "uncertain": 0.05
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of a change in offensive five-player lineup on the team's subsequent shot mix, specifically the distribution of shot attempts by zone (e.g., restricted area, paint non-restricted, mid-range, 3-point zones) and shot type (e.g., catch-and-shoot, pull-up, post-up, drive-and-kick).",
  "unit": "Offensive possessions. A 'change' event will be defined as a substitution that alters at least one player in the offensive five, marking the start of a new lineup's possessions.",
  "sample": "All offensive possessions from NBA 2022-23, 2023-24, and 2024-25 regular seasons and playoffs. Filter for possessions where the offensive lineup plays at least 5 minutes in that game to ensure a minimum sample for comparison within game context.",
  "power": "Target a minimum detectable effect size of a 2 percentage point shift in the proportion of shots from a specific zone for common lineup changes (e.g., changes occurring in >100 game segments across the dataset). Power calculations will be performed based on observed variance in shot mix within games and across lineups, aiming for 80% power at alpha=0.05 for these common changes.",
  "controls": "Control for game state (score differential, time remaining in quarter/game), opponent defensive scheme (derived from play-by-play data, e.g., zone vs. man, pick-and-roll coverage types), and individual player tendencies (e.g., each player's season-long average shot distribution). Use fixed effects for game, team, and potentially opponent to account for unobserved heterogeneity. A difference-in-differences approach comparing shot mix before and after a lineup change within the same game context will be considered.",
  "falsification": "Examine whether changes in shot mix occur when no personnel change has taken place but other control variables (game state, opponent defense) fluctuate similarly. Also, test for effects on defensive shot mix (which should not be directly influenced by offensive personnel changes) as a placebo control.",
  "multiplicity": "Adjust for multiple comparisons if testing effects across many specific shot zones or shot types. Bonferroni correction or False Discovery Rate (FDR) control will be applied depending on the number of hypotheses tested.",
  "decision_rule": "The hypothesis will be supported if statistically significant shifts in shot mix (p < 0.05 after multiplicity adjustment) are observed following offensive lineup changes, after controlling for confounding factors, and the effect size is considered practically meaningful (e.g., a change of at least 2 percentage points in a major shot zone).",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs per-game files from the NBA stats API (play-by-play, substitution rotation, starters, defensive matchup, box-score) and derived play-type possession records."
 }
}

